/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { BehaviorSubject } from 'rxjs';
import { TranslocoService, TRANSLOCO_CONFIG } from '@jsverse/transloco';
import { EditableRruleComponent } from './editable-rrule.component';
import { NoopAnimationsModule } from '@angular/platform-browser/animations';
import { RRule } from 'rrule';

class MockTranslocoService {
  config = { reRenderOnLangChange: false };
  langChanges$ = new BehaviorSubject('en');
  translate = jasmine.createSpy('translate').and.callFake((v: string) => v);
  setActiveLang = jasmine.createSpy('setActiveLang');
}

const PROVIDERS = [
  { provide: TranslocoService, useClass: MockTranslocoService },
  {
    provide: TRANSLOCO_CONFIG,
    useValue: { availableLangs: ['en'], defaultLang: 'en', reRenderOnLangChange: false, prodMode: true },
  },
];

describe('EditableRruleComponent', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('creates component', () => {
    TestBed.configureTestingModule({
      imports: [EditableRruleComponent, NoopAnimationsModule],
      providers: PROVIDERS,
    });
    const fixture = TestBed.createComponent(EditableRruleComponent);
    fixture.detectChanges();
    expect(fixture.componentInstance).toBeTruthy();
  });

  it('builds weekly rule with selected days', () => {
    TestBed.configureTestingModule({
      imports: [EditableRruleComponent, NoopAnimationsModule],
      providers: PROVIDERS,
    });
    const fixture = TestBed.createComponent(EditableRruleComponent);
    fixture.detectChanges();
    const comp = fixture.componentInstance;
    comp.patchState({ freq: 'WEEKLY', byWeekDay: [RRule.MO, RRule.WE, RRule.FR], interval: 1 });
    const str = comp.rule().toString();
    expect(str).toContain('FREQ=WEEKLY');
    expect(str).toContain('BYDAY=MO,WE,FR');
  });

  it('validates rruleNoDaysSelected for weekly with no days', () => {
    TestBed.configureTestingModule({
      imports: [EditableRruleComponent, NoopAnimationsModule],
      providers: PROVIDERS,
    });
    const fixture = TestBed.createComponent(EditableRruleComponent);
    fixture.detectChanges();
    const comp = fixture.componentInstance;
    comp.patchState({ freq: 'WEEKLY', byWeekDay: [] });
    expect(comp.validate(null as any)).toEqual(jasmine.objectContaining({ rruleNoDaysSelected: true }));
  });

  it('validates count must be positive', () => {
    TestBed.configureTestingModule({
      imports: [EditableRruleComponent, NoopAnimationsModule],
      providers: PROVIDERS,
    });
    const fixture = TestBed.createComponent(EditableRruleComponent);
    fixture.detectChanges();
    const comp = fixture.componentInstance;
    comp.patchState({ freq: 'DAILY', endMode: 'count', count: 0 });
    expect(comp.validate(null as any)).toEqual(jasmine.objectContaining({ rruleCountInvalid: true }));
  });
});
